import {assert} from './generation-purge-assert.mjs';
import {ArchiveRepository} from '../core/idb-repository.js';

const cases=[],test=(name,fn)=>{if(typeof name!=='string'||typeof fn!=='function')throw Error('native registration');cases.push({name,fn});};
let sequence=0;const repositories=[],ownedNames=new Set();
function nativeOptions(options){if(options?.indexedDB!==indexedDB)throw Error('native factory binding');const name=ownedNames.has(options.name)?options.name:'paia-native-source-incremental-matrix-'+(++sequence)+'-'+(options.name||'default');ownedNames.add(name);return {...options,name};}
function nativeStore(storage,options){const store=new LibraryDocumentsStore(storage,nativeOptions(options));repositories.push(store.repository);return store;}
function nativeRepository(storage,options){const repository=new ArchiveRepository(storage,nativeOptions(options));repositories.push(repository);return repository;}



export const local = () => { const data = {}; return {async get(k) {return {[k]:structuredClone(data[k])};}, async set(v) {Object.assign(data,structuredClone(v));}}; };
export const capture = (epoch, id = 'm1-synthetic-message-001', text = 'Synthetic explicit working input') => ({epoch,adapterVersion:'0.3.0',chat:{id:'m1-synthetic-chat',url:'https://chatgpt.com/c/m1-synthetic-chat',title:'Synthetic chat'},messages:[{sourceMessageId:id,pageOrder:1,originalText:text}]});
export async function inputEdit(s,id,changes) {const b=await s.input(id);return s.editDocument({operationId:crypto.randomUUID(),documentId:b.documentId,blocks:[{id,expectedRevision:b.revision,libraryText:b.libraryText,note:b.note,excluded:b.excluded,...changes}]});}
export async function derived(s,ids,extra={}) {const evidence=await s.evidenceFor(ids.map(inputId=>({inputId,role:'primary',selectedFields:['body']})));return s.createEntry({operationId:crypto.randomUUID(),actor:'ai',body:'Synthetic conclusion',type:'judgment',formation:ids.length>1?'synthesized':'explicit',evidence,generator:{providerId:'fixture',providerVersion:'1',modelVersion:'deterministic-1',taskSchemaVersion:1,promptTemplateVersion:1,policyVersion:1},...extra});}



import {LibraryDocumentsStore} from '../core/library-documents-store.js';

import {BrowserNativeSyncCore,sealOperation} from '../core/browser-native-sync/core.js';
import {SourceBootstrapJournal} from '../core/browser-native-sync/source-bootstrap-journal.js';
import {FilterIntentSyncJournal} from '../core/browser-native-sync/filter-intent-journal.js';
import {InputWorkingSyncJournal} from '../core/browser-native-sync/input-working-journal.js';
import {prepareCurrentSourceWorkingGroupCheckpointPlan} from '../core/browser-native-sync/group-checkpoint-plan.js';
import {prepareGroupScope} from '../core/browser-native-sync/group-checkpoint-scope.js';
import {assertSourceWorkingDefaultMeta,assertSourceWorkingRestoredDefaultMeta,assertSourceWorkingMergedDefaultMeta} from '../core/browser-native-sync/source-working-default-meta.js';
import {buildCheckpoint,StagedSyncRestore} from '../core/browser-native-sync/checkpoints.js';

const cloud=()=>{const objects=new Map();return {async putImmutable(ref,raw){objects.set(ref.id,raw.slice());},async get(ref){return objects.get(ref.id)?.slice();}};};
async function fresh(t,id){let time=Date.parse('2026-10-20T00:00:00Z');const store=nativeStore(local(),{indexedDB:indexedDB,clock:()=>new Date(time+=70000).toISOString()});await store.consent(true);await store.finishFoundation();t.after(()=>store.repository.db?.close());const core=new BrowserNativeSyncCore(store.repository,{datasetId:'synthetic-source-portfolio',deviceId:id});store.sourceBootstrapJournal=new SourceBootstrapJournal(core);store.filterIntentJournal=new FilterIntentSyncJournal(core);store.inputWorkingJournal=new InputWorkingSyncJournal(core,{filterJournal:store.filterIntentJournal,logicalCommits:true});return {store,core};}
const freeze=x=>{if(x&&typeof x==='object'){for(const y of Object.values(x))freeze(y);Object.freeze(x);}return x;};
async function cleanup(owner){let result;do{result=await owner.cleanup({limit:64});}while(!result.complete);}
async function state(side){const operations=[];for await(const row of side.core.rows('revision'))operations.push(row.operation);const plan=await prepareCurrentSourceWorkingGroupCheckpointPlan(side.core,operations),scope=await prepareGroupScope(plan),rows=await side.store.repository.transaction(false,async tx=>Object.fromEntries(await Promise.all(side.store.repository.stores.map(async name=>[name,await tx.all(name)]))));return {...side,plan,scope,rows:freeze(rows),control:structuredClone(side.store.controlCache),databaseId:side.store.databaseId};}
async function portfolio(t,{known=false,partial=false}={}){const side=await fresh(t,'synthetic-portfolio-A');for(let doc=0;doc<2;doc++)for(let item=0;item<2;item++){const request=capture((await side.store.status()).epoch,'synthetic-'+doc+'-'+item,'SYNTHETIC immutable source '+doc+' '+item);request.chat={id:'synthetic-chat-'+doc,url:'https://chatgpt.com/c/synthetic-chat-'+doc,title:'SYNTHETIC document '+doc};request.messages[0].pageOrder=item+1;if(known&&item===0)request.messages[0].sourceTime={state:'valid',createTime:1609459200+doc*86400,updateTime:null};await side.store.capture(request);}const blocks=(await side.store.snapshot()).library.blocks;for(const b of partial?blocks.slice(0,1):blocks)await inputEdit(side.store,b.id,{libraryText:'SYNTHETIC Working '+b.id,note:'SYNTHETIC note '+b.id});return side;}
async function cold(t,a,id,transport){const cut=await buildCheckpoint(a.core,transport,{grouped:{store:a.store}}),b=await fresh(t,id),restore=new StagedSyncRestore(b.core,{grouped:{store:b.store}});await restore.stageCheckpoint(cut.ref,r=>transport.get(r));await restore.activate();await cleanup(restore);return b;}
test('existing Source device retains its local edit and outbox while receiving another Input successor',async t=>{const a=await portfolio(t),transport=cloud(),b=await cold(t,a,'synthetic-incremental-B',transport),blocks=(await a.store.snapshot()).library.blocks;await inputEdit(b.store,blocks[1].id,{note:'SYNTHETIC B own edit'});await inputEdit(a.store,blocks[0].id,{note:'SYNTHETIC A remote edit'});const outbox=[];for await(const row of b.core.rows('outbox'))outbox.push(row);const cut=await buildCheckpoint(a.core,transport,{grouped:{store:a.store}}),receiver=new StagedSyncRestore(b.core,{grouped:{store:b.store}});await receiver.stageCheckpoint(cut.ref,r=>transport.get(r));assert.equal((await receiver.activate()).state,'activated');assert.equal((await b.store.input(blocks[0].id)).note,'SYNTHETIC A remote edit');assert.equal((await b.store.input(blocks[1].id)).note,'SYNTHETIC B own edit');const after=[];for await(const row of b.core.rows('outbox'))after.push(row);assert.deepEqual(after,outbox);await cleanup(receiver);const x=await state(b);await assertSourceWorkingRestoredDefaultMeta(x.core,x.scope,x.plan,x.rows,x.control,x.databaseId);const c=await cold(t,b,'synthetic-incremental-C',transport);assert.deepEqual((await c.store.snapshot()).library.blocks,(await b.store.snapshot()).library.blocks);});
async function snapshot(s){return s.store.repository.transaction(false,async tx=>Object.fromEntries(await Promise.all(s.store.repository.stores.map(async name=>[name,await tx.all(name)]))));}
async function incoming(t,{fork=false,checkpoint}={}){const a=await portfolio(t),transport=cloud(),b=await cold(t,a,'synthetic-incremental-B',transport),blocks=(await a.store.snapshot()).library.blocks;await inputEdit(b.store,blocks[fork?0:1].id,{note:'SYNTHETIC local preserved'});await inputEdit(a.store,blocks[0].id,{note:'SYNTHETIC incoming'});const cut=await buildCheckpoint(a.core,transport,{grouped:{store:a.store}}),restoreId=crypto.randomUUID(),receiver=new StagedSyncRestore(b.core,{restoreId,grouped:{store:b.store},checkpoint});await receiver.stageCheckpoint(cut.ref,r=>transport.get(r));return {a,b,blocks,transport,cut,restoreId,receiver};}
async function receive(t,from,to,transport){const cut=await buildCheckpoint(from.core,transport,{grouped:{store:from.store}}),r=new StagedSyncRestore(to.core,{grouped:{store:to.store}});await r.stageCheckpoint(cut.ref,x=>transport.get(x));await r.activate();await cleanup(r);return r;}
async function append(side,chat,id){const q=capture((await side.store.status()).epoch,id,'SYNTHETIC append '+id);q.chat={id:'synthetic-chat-'+chat,url:'https://chatgpt.com/c/synthetic-chat-'+chat,title:'SYNTHETIC document '+chat};q.messages[0].pageOrder=5;const before=new Set((await side.store.snapshot()).library.blocks.map(b=>b.id));await side.store.capture(q);const added=(await side.store.snapshot()).library.blocks.filter(b=>!before.has(b.id));assert.equal(added.length,1);await inputEdit(side.store,added[0].id,{note:'SYNTHETIC append Working '+id});return added[0].id;}
test('two devices append independently then receive in both directions and keep next local edits exportable',async t=>{const a=await portfolio(t),transport=cloud(),b=await cold(t,a,'synthetic-duplex-B',transport),aId=await append(a,0,'synthetic-extra-A'),bId=await append(b,1,'synthetic-extra-B');await receive(t,a,b,transport);await receive(t,b,a,transport);assert.equal((await a.store.snapshot()).records.length,6);assert.equal((await b.store.snapshot()).records.length,6);await inputEdit(a.store,aId,{note:'SYNTHETIC next A'});await inputEdit(b.store,bId,{note:'SYNTHETIC next B'});await receive(t,a,b,transport);await receive(t,b,a,transport);const c=await cold(t,a,'synthetic-duplex-C',transport);assert.equal((await c.store.input(aId)).note,'SYNTHETIC next A');assert.equal((await c.store.input(bId)).note,'SYNTHETIC next B');});
test('concurrent edits of the same Input are rejected before any canonical or protocol merge write',async t=>{const d=await incoming(t,{fork:true}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.deepEqual(await snapshot(d.b),before);});
test('duplicate and recreated consumer resolve the original durable merge receipt without writes',async t=>{const d=await incoming(t);await d.receiver.activate();const before=await snapshot(d.b);assert.equal((await d.receiver.activate()).state,'activated');const reopened=new StagedSyncRestore(new BrowserNativeSyncCore(d.b.store.repository,{datasetId:d.b.core.datasetId,deviceId:d.b.core.deviceId}),{restoreId:d.restoreId,grouped:{store:d.b.store}});assert.equal((await reopened.activate()).state,'activated');assert.deepEqual(await snapshot(d.b),before);});
test('lost committed result is resolved from durable receipts by an explicit recreated consumer',async t=>{const d=await incoming(t),original=d.b.store.foundationWrite.bind(d.b.store);let lost=false;d.b.store.foundationWrite=async(...args)=>{const result=await original(...args);if(result.merged){lost=true;throw Error('SYNTHETIC lost committed response');}return result;};await assert.rejects(d.receiver.activate());d.b.store.foundationWrite=original;assert.equal(lost,true);const before=await snapshot(d.b),reopened=new StagedSyncRestore(d.b.core,{restoreId:d.restoreId,grouped:{store:d.b.store}});assert.equal((await reopened.activate()).state,'activated');assert.deepEqual(await snapshot(d.b),before);});
for(const point of ['source-working-applied-group','before-source-working-commit'])test('failure at '+point+' rolls back the complete bounded checkpoint merge',async t=>{let injected=false;const d=await incoming(t,{checkpoint:async at=>{if(at===point){injected=true;throw Error('SYNTHETIC merge interruption');}}}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.equal(injected,true);assert.deepEqual(await snapshot(d.b),before);});
for(const mutation of ['unrelated-Source','old-receipt','local-outbox','foreign-negative-space','semantic-tail'])test('terminal fence refuses '+mutation+' drift and rolls back all tables',async t=>{let injected=false;const d=await incoming(t,{checkpoint:async(at,tx)=>{if(at!=='before-source-working-commit')return;injected=true;let table='meta',row;if(mutation==='unrelated-Source'){table='records';row=(await tx.all(table)).at(-1);row.value.originalText='SYNTHETIC tamper';}else if(mutation==='old-receipt'){row=(await tx.all('meta')).find(r=>r.id.includes(':receipt:'));row.digest='0'.repeat(64);}else if(mutation==='local-outbox'){row=(await tx.all('meta')).find(r=>r.id.includes(':outbox:'));await tx.delete('meta',row.id);return;}else if(mutation==='semantic-tail'){row=await tx.get('meta','aiu:delta:sequence');row.value+=100;}else{table='thoughtSuppressions';row={id:'synthetic-forbidden-owner',body:'SYNTHETIC forbidden'};}await tx.put(table,row);}}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.equal(injected,true);assert.deepEqual(await snapshot(d.b),before);});
test('original private work budget rejects 4097 reads even when public diagnostics are reset',async t=>{let injected=false;const d=await incoming(t,{checkpoint:async(at,tx)=>{if(at!=='before-source-working-commit')return;injected=true;try{for(let i=0;i<4097;i++)await tx.get('meta','synthetic-budget-probe');}finally{for(const key of Object.keys(tx.metrics))if(typeof tx.metrics[key]==='number')tx.metrics[key]=0;}}}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.equal(injected,true);assert.deepEqual(await snapshot(d.b),before);});
test('local edit after staging refuses the stale merge baseline and preserves the newer local state',async t=>{const d=await incoming(t);await inputEdit(d.b.store,d.blocks[2].id,{note:'SYNTHETIC later local baseline'});const before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.deepEqual(await snapshot(d.b),before);});

test('repeated unchanged checkpoint uses a new bounded no-op receipt without altering user data or outbox',async t=>{const d=await incoming(t);await d.receiver.activate();await cleanup(d.receiver);const before=await snapshot(d.b);const next=new StagedSyncRestore(d.b.core,{grouped:{store:d.b.store}});await next.stageCheckpoint(d.cut.ref,r=>d.transport.get(r));await next.activate();await cleanup(next);const after=await snapshot(d.b);for(const table of d.b.store.repository.stores)if(table!=='meta')assert.deepEqual(after[table],before[table]);assert.deepEqual(after.meta.filter(r=>r.id.includes(':outbox:')),before.meta.filter(r=>r.id.includes(':outbox:')));const x=await state(d.b);await assertSourceWorkingMergedDefaultMeta(x.core,x.scope,x.plan,x.rows,x.control,x.databaseId);});
test('timeline counterfeits and cross-receipt references cannot qualify a populated current cut',async t=>{const d=await incoming(t);await d.receiver.activate();await cleanup(d.receiver);const x=await state(d.b),mutations=[r=>r.batches[0].before='0'.repeat(64),r=>r.batches[0].after='0'.repeat(64),r=>r.batches[0].incoming=[r.base[0][0]],r=>r.batches[0].restoreId='synthetic-other-restore',r=>r.base.reverse(),r=>r.hiddenBody='SYNTHETIC unrepresented'];for(const mutate of mutations){const rows=structuredClone(x.rows);mutate(rows.meta.find(r=>r.id.endsWith(':sourceWorkingTimeline:')));freeze(rows);await assert.rejects(assertSourceWorkingMergedDefaultMeta(x.core,x.scope,x.plan,rows,x.control,x.databaseId));}});
test('late control revocation refuses the same atomic merge instead of adopting a fresh authority',async t=>{let injected=false;const d=await incoming(t,{checkpoint:async(at,tx)=>{if(at!=='before-source-working-commit')return;injected=true;const gate=await tx.get('meta','gate');await tx.put('meta',{...gate,enabled:false,epoch:gate.epoch+1});}}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.equal(injected,true);assert.deepEqual(await snapshot(d.b),before);});
test('elapsed public deadline rejects before commit and keeps the complete prior cut',async t=>{const now=performance.now.bind(performance),descriptor=Object.getOwnPropertyDescriptor(performance,'now');let elapsed=0,injected=false;Object.defineProperty(performance,'now',{configurable:true,value:()=>now()+elapsed});try{const d=await incoming(t,{checkpoint:async at=>{if(at==='before-source-working-commit'){injected=true;elapsed=30001;}}}),before=await snapshot(d.b);await assert.rejects(d.receiver.activate());assert.equal(injected,true);elapsed=0;assert.deepEqual(await snapshot(d.b),before);}finally{if(descriptor)Object.defineProperty(performance,'now',descriptor);else delete performance.now;}});
test('existing device admits a new original document bootstrap and its Working through the same bounded owner merge',async t=>{const a=await portfolio(t),transport=cloud(),b=await cold(t,a,'synthetic-new-document-B',transport),blocks=(await b.store.snapshot()).library.blocks;await inputEdit(b.store,blocks[0].id,{note:'SYNTHETIC B retained across new document'});const id=await append(a,2,'synthetic-new-conversation');await receive(t,a,b,transport);assert.equal((await b.store.snapshot()).library.documents.length,3);assert.equal((await b.store.input(id)).note,'SYNTHETIC append Working synthetic-new-conversation');assert.equal((await b.store.input(blocks[0].id)).note,'SYNTHETIC B retained across new document');const c=await cold(t,b,'synthetic-new-document-C',transport);assert.equal((await c.store.input(id)).note,'SYNTHETIC append Working synthetic-new-conversation');});
for(const mutation of ['queued-outbox','suppression-key','control-gate'])test('original Working owner return cannot establish a changed '+mutation+' baseline',async t=>{const d=await incoming(t),before=await snapshot(d.b),original=d.b.store.applyRemoteWorking.bind(d.b.store);let injected=false;d.b.store.applyRemoteWorking=async(tx,...args)=>{const result=await original(tx,...args);injected=true;if(mutation==='queued-outbox'){const row=(await tx.all('meta')).find(r=>r.id.includes(':outbox:'));assert.ok(row);await tx.delete('meta',row.id);}else{const id=mutation==='suppression-key'?'thought-suppression-key':'gate',row=await tx.get('meta',id);await tx.put('meta',mutation==='suppression-key'?{...row,value:row.value.map(v=>(v+1)%256)}:{...row,enabled:false,epoch:row.epoch+1});}return result;};await assert.rejects(d.receiver.activate());assert.equal(injected,true);assert.deepEqual(await snapshot(d.b),before);});

const previous=globalThis.__bnsNative;
globalThis.__bnsNative={...previous,async run(command,...args){
 if(command!=="source-incremental-matrix")return previous.run(command,...args);
 const passed=[];
 for(const item of cases){const after=[];let failure;
  try{await item.fn({after(fn){if(typeof fn!=='function')throw Error('native after');after.push(fn);}});passed.push(item.name);}
  catch(error){failure=Error(item.name+': '+error.stack);}
  finally{
   for(const fn of after.reverse())try{await fn();}catch(error){failure??=error;}
   for(const repository of repositories.splice(0))try{await repository.close();}catch(error){failure??=error;}
   for(const name of ownedNames){try{await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name);request.onsuccess=resolve;request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('native cleanup blocked'));});}catch(error){failure??=error;}}ownedNames.clear();
  }
  if(failure)throw failure;
 }
 return passed;
}};
